_CANDIDATES = {}


def _soundex(word):
    """ Soundex code of a word made of ASCII letters. """
    word = word.upper()
    r, last = word[0], SOUNDEX_DIGITS.get(word[0])
    for c in word[1:]:
        if (d := SOUNDEX_DIGITS.get(c)) and d != last:
            r += d
        # H and W do not separate consonants with the same digit, while vowels do
        if c not in "HW":
            last = d
    return (r + "000")[:4]


def __candidates():
    if not _CANDIDATES:
        for w in decompress(b64decode(SOUNDEX_WORDS)).decode().split():
            _CANDIDATES.setdefault(_soundex(w), []).append(w)
    return _CANDIDATES


def soundex_encode(text, errors="strict"):
    def _code(m):
        # letters without their accent (a word without ASCII letters, e.g. in another script, being kept as is)
        w = "".join(c for c in unicodedata.normalize("NFKD", m.group()) if c.isascii() and c.isalpha())
        return _soundex(w) if w else m.group()
    return re.sub(r"[^\W\d_]+", _code, ensure_str(text)), len(text)


def soundex_decode(variant=None):
    def decode(text, errors="strict"):
        _h, candidates = handle_error("soundex", errors, decode=True, kind="code"), __candidates()
        def _word(m):
            if (words := candidates.get(m.group().upper())) is None:
                return _h(m.group(), m.start())
            return words[0] if not variant or len(words) == 1 else f"[{'|'.join(words)}]"
        return re.sub(r"(?<![A-Za-z0-9])[A-Za-z]\d{3}(?![A-Za-z0-9])", _word, ensure_str(text)), len(text)
    return decode


add("soundex", lambda variant=None: soundex_encode, soundex_decode, r"^soundex(?:[-_](all))?$", examples=__examples__,
    guess=None)
